void long2string (long value, char *text)
{
DEBUG_OUT("long2string Enter");

	char string[32];

	if (value >= 100000000)
	{
		strcpy (text, "Huge!");
		return;
	}
	sprintf (string, "%7d", (int)value);
	string[8] = 0;
	strcpy (text, (char *)string);
}

