//--------------------------------
void KerrStinnEditor::setParameter(long index, float value)
{
DEBUG_OUT("setParameter Enter");
    if(!frame)
        return;
    switch(index)
    {
		case kRand:
			if(nRand)
				nRand->setValue(effect->getParameter(index));
			//if(myDrop)
			//	myDrop->setValue(effect->getParameter(index));
		break;
 		case kSlices:
			if(nSlices)
				nSlices->setValue(effect->getParameter(index));
		break;
		case kBisyness:
			if(nBisyness)
				nBisyness->setValue(effect->getParameter(index));
		break;
 		case kGenerationMatrix:
	//		cOptionMenu->setValue(int((effect->getParameter(index)*(float)(DnumTypes-1)+0.99)) );
			if(nGenerationMatrix)
				nGenerationMatrix->setValue(effect->getParameter(index));
		break;
		case kNumBars:
			if(nNumBars)
				nNumBars->setValue(effect->getParameter(index));
		break;
		case kOn:
			if(onOff)
				onOff->setValue(effect->getParameter(index));
		break;
  
		break;
    }



	char tempchNumBars[64];
	char tempchSeed[64];
	char tempchSlices[64];
	char tempchBisyness[64];
	char tempchGenerationMatrix[64];

 	this->effect->getParameterDisplay(kNumBars,tempchNumBars);
	this->effect->getParameterDisplay(kRand,tempchSeed);
 	this->effect->getParameterDisplay(kSlices,tempchSlices);
	this->effect->getParameterDisplay(kBisyness,tempchBisyness);
	this->effect->getParameterLabel(kGenerationMatrix,tempchGenerationMatrix);

 	 nRandTXT->setText((tempchSeed));
 	 nSlicesTXT->setText((tempchSlices));
 	 nBisynessTXT->setText((tempchBisyness));
 	 nNumBarsTXT->setText((tempchNumBars));
	 nGenerationMatrixTXT->setText((tempchGenerationMatrix));
 	 this->frame->setDirty(true);
}

//--------------------------------
void KerrStinnEditor::valueChanged(CDrawContext* context, CControl* control)
{
DEBUG_OUT("valueChanged Enter");
//    char tempch[64];
	    long tag = control->getTag();
	//	effect->setParameterAutomated(tag, control->getValue());
	if (tag == 666)
		{
			((AKerrStinn*)(effect))->loadFile(myOscilloscope->getFileName());
			fileChanged=true;
			int lastError = ((AKerrStinn*)(effect))->myEngine.getLastError();
			if (lastError == 0)
				nEngineErrorTXT->setText("Initialized, life is fine and dandy Mr Montroe");
			if (lastError == 1)
				nEngineErrorTXT->setText("Bad pointer to file, how could you let this happen");
			if (lastError == 2)
				nEngineErrorTXT->setText("Bad bad wave, misbehaving!!!");
			else
				nEngineErrorTXT->setText("KERRSTINN: WEAPON OF BREAK CONSTRUCTION");
				

 
		}
		 
	//		if (control== cOptionMenu)
	//		{
			//wtf, dŠr skall finnas 26 styckenna
			//vilket borde betuda att varje Šr vŠrd en 26'e del av the value?
	//			effect->setParameterAutomated(tag, (1.0/26.0)*control->getValue());

		//	}
			 
	effect->setParameterAutomated(tag, control->getValue());
	control->setDirty(true);
	frame->setDirty(true);
	
	
}

